local R=require('rendering');local G=require('genome');local A=require('anatomy');local S=require('persistence');local P=require('body_parts');local B=require('biology');local T={}
local root
local function write(name,value) local f=assert(io.open(root..'/'..name,'wb'));f:write(value);f:close() end
local function seed(i) return (20261112+i*104729)%2147483647 end
local function make(i,conditions) local g=G.new(G.rng(seed(i)));return A.generate(g,conditions or {seed=seed(i),nutrition=1,temperature=37}),g end
function T.run()
 root=love.filesystem.isFused() and love.filesystem.getSourceBaseDirectory() or love.filesystem.getSource()
 local lines={};local failures=0;local function test(name,fn) local ok,why=xpcall(fn,debug.traceback);lines[#lines+1]=(ok and 'PASS ' or 'FAIL ')..name..(ok and '' or '\n'..why);if not ok then failures=failures+1 end end
 local a,g=make(1)
 test('Deterministic genome, seed and developmental environment',function() local b=A.generate(G.copy(g),a.development);assert(S.encode(a)==S.encode(b));assert(G.valid(g) and #g.chromosomes==24) end)
 test('Parent connectivity and supported joint limits',function() for i=1,100 do local b=make(i);for j,r in ipairs(b.regions) do assert(j==1 or r.parent<j);assert(b.components[r.structure].regionId==j) end;for _,j in ipairs(b.joints) do assert(b.components[j.parent] and b.components[j.child] and j.maximum>j.minimum) end end end)
 test('Muscles span distinct structural supports',function() for _,m in ipairs(a.muscles) do assert(m.origin~=m.insertion and a.components[m.origin] and a.components[m.insertion]) end end)
 test('Every functional part has brain-to-motor nerve connectivity',function() local b=G.copy(a);b.nerves={};local ok,why=P.validate(b);assert(not ok and table.concat(why):find('neural path'));assert(P.validate(a)) end)
 test('Cavities contain organs and reject collisions',function() assert(P.validate(a));local b=G.copy(a);b.organs[1].cx=999;assert(not P.validate(b));b=G.copy(a);b.organs[#b.organs+1]=G.copy(b.organs[1]);assert(not P.validate(b)) end)
 test('Tissue volume conservation and physical mass ledger',function() for i=1,100 do local b=make(i);local mass=0;for _,r in ipairs(b.regions) do local total=0;for _,c in ipairs(b.components) do if c.regionId==r.id then assert(c.volume>=0 and c.mass>=0);total=total+c.volume;mass=mass+c.mass end end;assert(total<=r.volume+1e-8) end;assert(math.abs(mass-b.caps.mass)<1e-8) end end)
 test('Regional dorsal armor does not protect ventral abdomen',function() local b=G.copy(a);local before=P.defense(b,2,'ventral');for _,c in ipairs(b.components) do if c.type=='Skin' and c.regionId==1 and c.surface=='dorsal' then c.armor=c.armor+100 end end;assert(P.defense(b,1,'dorsal')>99 and P.defense(b,2,'ventral')==before) end)
 test('Physical stats respond to muscle, mass, organ and tissue condition',function() local b=G.copy(a);for _,c in ipairs(b.components) do if c.type=='Muscle' then c.force=0 end end;assert(A.capabilities(b,g).force==0);for _,c in ipairs(b.components) do if c.type=='Heart' then c.condition=0 end end;assert(A.capabilities(b,g).supply==0);assert(a.caps.force>0) end)
 test('Self-inheritance preserves homozygous anatomy; mutation changes development',function() local h=G.copy(g);for _,ch in ipairs(h.chromosomes) do for _,l in ipairs(ch.loci) do l.b=l.a end end;local child=assert(G.fertilize(G.gamete(h,G.rng(8),1,0),G.gamete(h,G.rng(9),2,0)));local p=A.generate(h);local c=A.generate(child);assert(p.appendageCount==c.appendageCount and p.headCount==c.headCount and p.caps.mass==c.caps.mass);local changed=G.mutate(child,G.rng(66),1,'test');assert(changed>0);assert(A.generate(child).caps.mass~=c.caps.mass) end)
 test('Biological failure retains actual body, never substitutes fallback',function() local b=A.generate(g,{nutrition=.01,temperature=0});assert(not b.viable and b.generator=='anatomical-blocks-v1' and not b.technicalFallback) end)
 test('Save/load preserves canonical genome and anatomy identity',function() local state=B.new(43);local o=assert(B.spawn(state,g,'test',0,.5,.5,a));local decoded=assert(S.decode('return '..S.encode(state),B));local b=decoded.organisms[1];assert(G.hash(b.genome)==G.hash(g) and b.anatomy.anatomicalVersion==1);assert(b.anatomy.parts==b.anatomy.regions and b.anatomy.structures[1]==b.anatomy.components[b.anatomy.structures[1].id]);assert(b.caps.mass==o.caps.mass) end)
 test('Recorded construction stages preserve final graph',function() local frames=a.snapshots;assert(#frames>8 and #frames[1].regions==1 and frames[1].regions[1].length==2);assert(#frames[1].components==0);assert(S.encode(frames[#frames].regions)==S.encode(a.regions));assert(S.encode(frames[#frames].components)==S.encode(a.components));assert(#frames[3].regions<#a.regions) end)
 test('Old procedural and legacy records retain their generators and physiology',function() local old=A.procedural(g);local b=S.rebind(G.copy(old));assert(not b.anatomicalVersion and A.capabilities(b,g).mass>0);local legacy=A.generate(g,{generator='legacy'});assert(not legacy.anatomicalVersion and legacy.generator=='legacy-fallback') end)
 test('Forge/archive/incubation/PC-clock laboratory integration',function() local state=B.new(23);local E=require('genome_editor');E.begin({genome=g,id=1});assert(E.commit(state,B));assert(G.hash(state.materials[1].genome)==G.hash(g));local D=require('development');local embryo=D.new(5,g,'test',1,{nutrition=1,temperature=37});D.update(embryo,10);assert(embryo.anatomy.anatomicalVersion and embryo.constructionFrame);local ok;for i=1,500 do ok=D.update(embryo,.1);if ok~=nil then break end end;assert(ok==true);local o=assert(B.spawn(state,g,'test',0,.5,.5,embryo.anatomy));B.update(state,.1);assert(o.stats and o.caps.compatibility);local clock=require('realtime');clock.start(state);assert(state.clock);local t=state.time;require('anatomy_dev_ui').generate(seed(1));require('anatomy_dev_ui').playing=true;require('anatomy_dev_ui').update(5);assert(state.time==t) end)
 test('Joint motion remains within limits with connected descendant transforms',function() local V=require('anatomical_rendering');for i=0,10 do local posed=V.pose(a,i);for _,j in ipairs(posed.joints) do assert(j.playbackAngle>=j.minimum and j.playbackAngle<=j.maximum) end;for _,r in ipairs(posed.regions) do if r.start then local dx,dz=r.finish.x-r.start.x,r.finish.z-r.start.z;assert(math.abs(math.sqrt(dx*dx+dz*dz)-r.length)<1e-6 or a.symmetry=='radial') end end end end)
 test('Developmental allele edits alter real heads and appendages',function() local edited=G.copy(g);edited.chromosomes[6].loci[2].a=0;edited.chromosomes[6].loci[2].b=0;edited.chromosomes[14].loci[2].a=0;edited.chromosomes[14].loci[2].b=0;local body=A.generate(edited);assert(a.appendageCount>0 and a.headCount>0 and body.appendageCount==0 and body.headCount==0);assert(#body.regions<#a.regions) end)
 local audits={}
 for _,count in ipairs({100,1000}) do
  local r={count=count,viable=0,developmentalFailures=0,technicalErrors=0,symmetry={},appendages={},heads={},configurations={},commonFailures={},mass={min=math.huge,max=0},muscle={min=math.huge,max=0},skeleton={min=math.huge,max=0},samples={}}
  local function inc(t,k) t[k]=(t[k] or 0)+1 end
  for i=1,count do local ok,b=pcall(make,i);if not ok then r.technicalErrors=r.technicalErrors+1;r.samples[#r.samples+1]={seed=seed(i),error=tostring(b)} else
   if b.viable then r.viable=r.viable+1 else r.developmentalFailures=r.developmentalFailures+1 end
   inc(r.symmetry,b.symmetry);inc(r.appendages,b.appendageCount);inc(r.heads,b.headCount)
   local signature=b.symmetry..'/'..b.appendageCount..'/'..b.headCount..'/'..b.segments..'/'..#b.joints;inc(r.configurations,signature)
   for _,why in ipairs(b.failures) do inc(r.commonFailures,why) end
   local pm=b.caps.physicalMass;for key,value in pairs({mass=b.caps.mass,muscle=pm.Muscle or 0,skeleton=(pm.Bone or 0)+(pm.Support or 0)+(pm.Carapace or 0)}) do r[key].min=math.min(r[key].min,value);r[key].max=math.max(r[key].max,value) end
   r.samples[#r.samples+1]={seed=seed(i),hash=b.genomeReference,viable=b.viable,symmetry=b.symmetry,appendages=b.appendageCount,heads=b.headCount,mass=b.caps.mass,failures=b.failures}
  end end
  local n=0;for _ in pairs(r.configurations) do n=n+1 end;r.distinctConfigurations=n;audits[count]=r
  write('anatomy-audit-'..count..'.lua','return '..S.encode(r))
  write('docs/ANATOMY_AUDIT_'..count..'.md',table.concat({'# Actual '..count..'-genome audit','','Unfiltered G.new genomes, i=1..'..count..'. Seed = (20261112 + i * 104729) mod 2147483647. Standard nutrition, 98.6 °F. Same generator as Forge and incubation. No retries or viability filtering.','',string.format('Viable %d; developmental failures %d; technical errors %d; distinct configurations %d.',r.viable,r.developmentalFailures,r.technicalErrors,n),'','Symmetry: '..S.encode(r.symmetry),'Appendages: '..S.encode(r.appendages),'Heads: '..S.encode(r.heads),'','Mass (oz): '..S.encode(r.mass),'Muscle (oz): '..S.encode(r.muscle),'Skeletal tissue (oz): '..S.encode(r.skeleton),'','Failures: '..S.encode(r.commonFailures),'','Contact sheet selection: first 20 genomes of the 100-genome run, including failures.'},'\n'))
 end
 test('Unfiltered 1000 audit has viable and diverse inheritable bodies without technical fallback',function() local r=audits[1000];assert(r.technicalErrors==0 and r.viable>0 and r.distinctConfigurations>30 and r.appendages[0] and r.appendages[2] and r.appendages[6] and r.heads[0] and r.heads[2]);assert((r.appendages[4] or 0)<r.count*.6) end)
 test('Real side-view contact sheet, layers, playback and desktop tool render',function()
  local canvas=love.graphics.newCanvas(1600,1300);love.graphics.push('all');love.graphics.setCanvas(canvas);love.graphics.clear(.055,.09,.115);love.graphics.setFont(love.graphics.newFont(14));love.graphics.setColor(.85,.94,.91);love.graphics.print('CELLARIUM / FIRST 20 UNFILTERED GENOMES / same seeds as audit / failures retained',20,15)
  for i=1,20 do local b,h=make(i);local col,row=(i-1)%4,math.floor((i-1)/4);local x,y=col*400,row*250+50;love.graphics.setColor(.09,.14,.17);love.graphics.rectangle('fill',x+8,y,384,236,6);local scale=R.fitScale(b,350,160,2);local cx,cy=(b.bounds.minx+b.bounds.maxx)/2,(b.bounds.miny+b.bounds.maxy)/2;R.draw({anatomy=b,genome=h,caps=b.caps,alive=true,maturity=1,behavior='Resting'},x+200-cx*scale,y+100-cy*scale,scale,0,'External');love.graphics.setColor(b.viable and .65 or 1,.8,.72);love.graphics.print('Seed '..seed(i)..' / '..(b.viable and 'VIABLE' or 'FAILED'),x+18,y+185);love.graphics.setColor(.65,.76,.8);love.graphics.print(b.symmetry..' / '..b.appendageCount..' limbs / '..b.headCount..' heads',x+18,y+208) end
  love.graphics.setCanvas();write('docs/ANATOMY_CONTACT_SHEET.png',canvas:newImageData():encode('png'):getString());love.graphics.pop()
  local ui=require('anatomy_dev_ui');ui.generate(seed(1));for _,layer in ipairs(R.layers) do R.draw({anatomy=ui.anatomy,alive=true,maturity=1},0,0,1,0,layer) end
  local s=B.new(1);require('desktop_model').ensure(s);local app=require('desktop_app');app.page='Anatomy Generator';canvas=love.graphics.newCanvas(1440,900);love.graphics.push('all');love.graphics.setCanvas(canvas);app.draw(s,{register=function() end});love.graphics.setCanvas();write('docs/ANATOMY_GENERATOR.png',canvas:newImageData():encode('png'):getString());love.graphics.pop()
  for frame=1,#ui.anatomy.snapshots do ui.frame=frame;R.draw({anatomy=ui.frameAnatomy(),alive=true,maturity=1},0,0,1,0,{Skeleton=true,Muscle=true,Organs=true,Nervous=true}) end
 end)
 test('Developer controls: seed entry, recorded replay, archive and export callbacks',function() local ui=require('anatomy_dev_ui');local app=require('desktop_app');local state=B.new(4);require('desktop_model').ensure(state);local hits={};local function draw() hits={};app.draw(state,{register=function(x,y,w,h,fn,label) hits[label]=fn end}) end;app.page='Settings';require('desktop_host').monitors={};draw();assert(hits['Anatomy Generator / developer tool']);hits['Anatomy Generator / developer tool']();draw();hits['Seed: '..ui.seed]();assert(app.textinput(tostring(seed(1))));assert(app.keypressed('return'));assert(ui.seed==tostring(seed(1)));draw();hits.Restart();assert(ui.frame==1);draw();hits.Step();assert(ui.frame==2);local before=#state.materials;draw();hits['Save Genome']();assert(#state.materials==before+1);local name=assert(ui.export(root..'/anatomy-export-test.lua'));local file=assert(io.open(name,'rb'));local raw=file:read('*a');file:close();assert(raw:find('genomeReference'));assert(os.remove(name)) end)
 lines[#lines+1]=string.format('%d groups executed; %d failures.',#lines,failures);write('anatomy-test-results.txt',table.concat(lines,'\n'));assert(failures==0,table.concat(lines,'\n'));return table.concat(lines,'\n')
end
return T
